                throw new BusinessException("OSS upload wechat bill failed: download file path - " + downloadFilePath);
            } else {
                log.info("OSS wechat bill backup is done. target path:{}", fileHandleTaskDo.getTargetServerNo() + "," + fileHandleTaskDo.getTargetFilePath());
            }

            localFile = new File(downloadFilePath, sourceFileName);

            if (!localFile.exists()) {
                throw new BusinessException("Local file not found:" + downloadFilePath + File.separator + sourceFileName);
            }

            if (fileHandleTaskDo.getHandleDt() == null) {
                throw new BusinessException("Missing handle Date");
            }

            FileTunnelDTO result = wechatDetailOdpsTunnelServiceImp.tunnelLessDataOdps(downloadFilePath, sourceFileName, fileHandleTaskDo);

            log.info("wechat Tunnel Success - {}", result.toString());

            if (result.isSuccess()) {
                fileHandleTaskDo.setHandleStatus(FileHandleStatus.SUCCESS.getCode());
                fileHandleTaskTunnel.update(fileHandleTaskDo);
