            String downloadFilePath = localFilePath + Constant.RESOURCE + "/" + fileHandleTaskNo;

            fileHandleTaskDo.setSourceFilePath(downloadFilePath);

            File localFile = null;

            if (StringUtils.isBlank(targetFileName)) {
                fileHandleTaskDo.setTargetFileName(sourceFileName);
            }

            try {
                List<String> fileNames = new ArrayList<>();

                /**
                 * download from cmbc
                 */
                sourceFileName = downloadBillService.downloadBill(fileHandleTaskDo);
                if(!org.springframework.util.StringUtils.isEmpty(sourceFileName)){
                    fileNames.add(sourceFileName);
                }

                /**
                 * upload to oss for backup
                 */
                boolean flag = ossFileHandleService.upload(fileHandleTaskDo, targetFileServerDo, fileNames, downloadFilePath);

                if (!flag) {
                    throw new BusinessException("OSS upload cmbc bill failed: download file path - " + downloadFilePath);
                } else {
                    log.info("OSS cmbc bill backup is done. target path:{}", fileHandleTaskDo.getTargetServerNo() + "," + fileHandleTaskDo.getTargetFilePath());
                }

                localFile = new File(downloadFilePath, sourceFileName);

                if (!localFile.exists()) {
                    throw new BusinessException("Local file not found:" + downloadFilePath + File.separator + sourceFileName);
                }

                if (fileHandleTaskDo.getHandleDt() == null) {
                    throw new BusinessException("Missing handle Date");
                }

                FileTunnelDTO result = cmbcDetailOdpsTunnelServiceImp.tunnelLessDataOdps(downloadFilePath, sourceFileName, fileHandleTaskDo);

                log.info("cmbc Tunnel Success - {}", result.toString());

                if (result.isSuccess()) {
                    fileHandleTaskDo.setHandleStatus(FileHandleStatus.SUCCESS.getCode());
                    fileHandleTaskTunnel.update(fileHandleTaskDo);
                }
            } catch (Exception exp) {
                if (exp instanceof BusinessException) {
                    BusinessException businessExp = (BusinessException) exp;
                    log.error("cmbc File handle task no:{}, exception:{}", fileHandleTaskNo, businessExp.getDetailMessage());
                } else {
                    log.error("cmbc File handle task no:{}, exception:{}", fileHandleTaskNo, exp);
                }

                fileHandleTaskDo.setHandleStatus(FileHandleStatus.INIT.getCode());

                fileHandleTaskTunnel.update(fileHandleTaskDo);

            } finally {
                FileUtils.delete(localFile);
            }
        } else {
            //申请作业流水号
            String askSerialNoDownload = downloadBillService.preDownload(fileHandleTaskDo);
            JSONObject jsonObject = new JSONObject();
            jsonObject.put("askSerialNoDownload", askSerialNoDownload);
            fileHandleTaskDo.setExtendInfo(jsonObject.toJSONString());

            if (askSerialNoDownload.equals("no data")) {
                //查不到数据直接关闭任务
                fileHandleTaskDo.setHandleStatus(FileHandleStatus.SUCCESS.getCode());
            }
            fileHandleTaskTunnel.update(fileHandleTaskDo);


        }

    }

