@Override
	public void handle(FileHandleTaskDo fileHandleTaskDo, FileServerDo sourceFileServerDo,
					   FileServerDo targetFileServerDo, String baseFilePath) {

		String fileHandleTaskNo = fileHandleTaskDo.getFileHandleTaskNo();

		String localFilePath = baseFilePath + File.separator + FileHandleType.DIFF_TUNNRL_HANDLE.getCode();

		String sourceFileName = fileHandleTaskDo.getSourceFileName();
		Integer sourceServerType = sourceFileServerDo.getServerType();

		String targetFileName = fileHandleTaskDo.getTargetFileName();

		String downloadFilePath = localFilePath + File.separator + Constant.RESOURCE;

		File localFile = null;


		if(StringUtils.isBlank(targetFileName)) {
			fileHandleTaskDo.setTargetFileName(sourceFileName);
		}

		FilterInputStream fileInputStream = null;
		try {
			//校验ODPS实例是否已生成，未生成则直接返回
			if(LocalDateTime.now().isBefore(DateUtil.convertDateTime(fileHandleTaskDo.getHandleDt()).plusDays(1))){
				throw new BusinessException("ODPS instance has not been generated");
			}
			List<String> fileNames = null;

			/**
			 * download from sftp
			 */
			FileUtil.createFolder(downloadFilePath);
			if (Objects.equals(sourceServerType, FileServerType.SFTP.getCode())) {
				fileNames = sftpFileHandleService.download(fileHandleTaskDo, sourceFileServerDo, downloadFilePath);
			}

			if (!Objects.equals(sourceServerType, FileServerType.SFTP.getCode()) || CollectionUtils.isEmpty(fileNames)) {
				throw new BusinessException("Source server type not sftp or empty files - source server type:" + sourceServerType);
			} else {
				String fileNamesText = Joiner.on(",").join(fileNames);
				log.info("SFTP download is done-download file path:{},source server url:{}, file names:{}"
						,downloadFilePath ,sourceFileServerDo.getUrl(),fileNamesText);
			}


			/**
			 * upload to oss for backup
			 */
			boolean flag= ossFileHandleService.upload(fileHandleTaskDo, targetFileServerDo, fileNames, downloadFilePath);

			if(!flag) {
				throw new BusinessException("OSS upload failed: download file path - " + downloadFilePath);
			} else {
				log.info("OSS backup is done. target path:{}",fileHandleTaskDo.getTargetServerNo() + "," + fileHandleTaskDo.getTargetFilePath());
			}


			localFile = new File(downloadFilePath, sourceFileName);

			if(localFile == null || !localFile.exists()) {
				throw new BusinessException("Local file not found:" + downloadFilePath + File.separator + sourceFileName);
			}

			if(fileHandleTaskDo.getHandleDt() == null) {
				throw new BusinessException("Missing handle Date");
			}

			/**
			 * tunnel less diff data to odps
			 */
			String extention = GzipCompressUtils.getExtension(sourceFileName);
			if("gz".equals(extention) || "rar".equals(extention)) {
				fileInputStream = new GZIPInputStream(new FileInputStream(localFile));
			} else {
				fileInputStream = new BufferedInputStream(new FileInputStream(localFile));
			}

			FileTunnelDTO result = reconCoreOdpsTunnelService.tunnelLessDataOdps(fileInputStream, fileHandleTaskDo);
			log.info("Tunnel Success - {}", result.toString());
			if(!result.isSuccess()) {
				throw new BusinessException("tunnelLessDataOdps unknown exception");
			}
			fileHandleTaskDo.setHandleStatus(FileHandleStatus.SUCCESS.getCode());
			fileHandleTaskTunnel.update(fileHandleTaskDo);

            //触发ODPS任务执行
			RunTriggerNodeRequest runTriggerNodeRequest = this.buildRunTriggerNodeRequest(fileHandleTaskDo.getHandleDt());
			RunTriggerNodeResponse runTriggerNodeResponse = ReconOdpsUtil.runTriggerNodes(runTriggerNodeRequest, reconOdpsConfig);
			log.info(JSON.toJSONString(runTriggerNodeResponse));
			if(runTriggerNodeResponse != null && !runTriggerNodeResponse.getSuccess()){
				log.warn("runTriggerNodes failed, param:{}", JSON.toJSONString(runTriggerNodeRequest));
				dingErrorMsgComponent.sendAlarm("runTriggerNodes task failed!, fileHandleTaskNo:{}", fileHandleTaskNo);
			}
		} catch(Exception exp) {
			if(exp instanceof BusinessException) {
				BusinessException businessExp = (BusinessException)exp;
				log.error("File handle task no:{}, exception:{}",fileHandleTaskNo, businessExp.getDetailMessage());
			} else {
				log.error("File handle task no:{}, exception:{}", fileHandleTaskNo, exp);
			}
			fileHandleTaskDo.setHandleStatus(FileHandleStatus.INIT.getCode());
			fileHandleTaskTunnel.update(fileHandleTaskDo);

		}finally {
			FileUtils.delete(localFile);
			if(fileInputStream != null) {
				FileUtils.close(fileInputStream);
			}
		}


	}

