public static boolean decompression(String zipPath, String outPutPath, String charset) {
        log.info("decompression 开始解压的压缩包路径：{}，编码格式：{}，压缩之后的文件存放路径：{}", zipPath, charset, outPutPath);
        long startTime = System.currentTimeMillis();
        //输入源zip路径
        try (ZipInputStream zin = new ZipInputStream(new FileInputStream(zipPath), Charset.forName(charset));
             BufferedInputStream bin = new BufferedInputStream(zin)) {
            String parent = outPutPath;
            ZipEntry entry;
            while ((entry = zin.getNextEntry()) != null && !entry.isDirectory()) {
                File fOut = new File(parent, entry.getName());
                if (!fOut.exists()) {
                    File parentFile = new File(fOut.getParent());
                    parentFile.mkdirs();
                }
                try (FileOutputStream out = new FileOutputStream(fOut);
                     BufferedOutputStream bout = new BufferedOutputStream(out)) {
                    int b;
                    while ((b = bin.read()) != -1) {
                        bout.write(b);
                    }
                } catch (IOException e) {
                    log.error("decompression 解压文件出现异常，压缩包路径：{}", zipPath, e);
                    return false;
                }
            }
        } catch (FileNotFoundException fe) {
            log.error("decompression 解压的压缩包文件没有找到，压缩包路径：{}", zipPath, fe);
            return false;
        } catch (IOException e) {
            log.error("decompression 解压的压缩包文件异常，压缩包路径：{}", zipPath, e);
            return false;
        }
        long endTime = System.currentTimeMillis();
        log.info("decompression 完成解压的压缩包路径：{}，编码格式：{}，压缩之后的文件存放路径：{}，耗费时间：{}", zipPath, charset, outPutPath,
                (endTime - startTime) + " ms");
        return true;
    }

