@Override
	public FileTunnelDTO tunnelLessDataOdps(FilterInputStream fileInputStream, FileHandleTaskDo fileHandleTaskDo) 
		throws BusinessException {
		
		final int tunnelBufferedSize = bufferSizeinMB * 1024 * 1024;
		final int fileBufferedSize = fileBufferSize * 1024;
		
		String fileHandleTaskNo = fileHandleTaskDo.getFileHandleTaskNo();
		Date handleDT = fileHandleTaskDo.getHandleDt();
		
		final RetryStrategy retryStrategy = new RetryStrategy(6, 4);
		String tableName = OdpsTableEnum.ANT_RECON_BIZ_BILL.getTableName();
		
		String tablePartition = DateUtil.getDateTimeFromNow(handleDT);
		
		PartitionSpec partitionSpec = new PartitionSpec("pt=" + tablePartition);
		
		/**
		 * cleanup partition data
		 */
		String cleanPartitionSql = String.format(CLEAN_PARTITION_SQL_FORMAT, odpsTargetProject, tableName, tablePartition); 
	    runSql(cleanPartitionSql);
		log.info("partiton is cleanup:{}", cleanPartitionSql);
		
		String createPartitionSql = String.format(NEW_PARTITION_SQL_FORMAT, odpsTargetProject, tableName, tablePartition); 
	    runSql(createPartitionSql);
		log.info("partiton is created:{}", cleanPartitionSql);
		
		/**
		 * create table tunnel
		 */
		TunnelBufferedWriter recordWriter = null;
		
		String text = null;
		int numOfTunnel = 0;
		Stopwatch watch = Stopwatch.createStarted();

		ZipEntry ze = null;
		try {
			TableTunnel.UploadSession uploadSession = odpsTableTunnel.createUploadSession(odpsTargetProject, tableName,
					partitionSpec);
			recordWriter = (TunnelBufferedWriter)uploadSession.openBufferedWriter();
			recordWriter.setRetryStrategy(retryStrategy);
			recordWriter.setBufferSize(tunnelBufferedSize);
			//读取一个文件
			ZipInputStream zin = (ZipInputStream)fileInputStream;
			while((ze = zin.getNextEntry()) != null){
				//统计条数
				AtomicInteger count = new AtomicInteger(-1);
				if(ze.isDirectory()){
					//为空的文件夹什么都不做
					continue;
				}
				BufferedReader reader = new BufferedReader(new InputStreamReader(zin, Constant.GBK), fileBufferedSize);
				while (reader.ready()) {
					text = reader.readLine();
					//跳过表头
					if(count.getAndIncrement() == -1){
						continue;
					}
					if(StringUtils.isNotBlank(text)) {
						Record record = uploadSession.newRecord();
						String[] columns = StringUtils.split(text, Constant.SEPARATOR);
						if(columns.length < 22){
							log.info("FileHandleTaskNo:{}  fileName: {}, column :{}, text:{}, column size:{}", fileHandleTaskNo, ze.getName(), count.get(), text, columns.length);
						}
						record.setString("biz_dt", StringUtils.trimToNull(columns[0]));
						//业务类型
						String bizType = StringUtils.trimToNull(columns[1]);
						String policyNo = StringUtils.trimToNull(columns[2]);
						String bizVouhourNo = StringUtils.trimToNull(columns[3]);
						record.setString("biz_type", bizType);
						record.setString("policy_no", policyNo);
						record.setString("biz_vouhour_no", bizVouhourNo);
						record.setString("standard_product_code", StringUtils.trimToNull(columns[4]));
						record.setString("org_product_code", StringUtils.trimToNull(columns[5]));
						record.setString("product_name", StringUtils.trimToNull(columns[6]));
						record.setString("org_id", StringUtils.trimToNull(columns[7]));
						record.setString("is_issue", StringUtils.trimToNull(columns[8]));
						record.setString("income_or_expenses", StringUtils.trimToNull(columns[9]));
						record.setString("refund_type", StringUtils.trimToNull(columns[10]));
						record.setString("biz_remark", StringUtils.trimToNull(columns[11]));
						record.setDatetime("biz_complete_dt", DateUtil.getDate(StringUtils.trimToNull(columns[12])));
						record.setDatetime("pay_dt", DateUtil.getDate(StringUtils.trimToNull(columns[13])));
						record.setString("alipay_trade_no", StringUtils.trimToNull(columns[14]));
						record.setDecimal("receivable_premium", StringUtil.getBigDecimal(columns[15]));
						record.setDecimal("pay_amount", StringUtil.getBigDecimal(columns[16]));
						record.setDecimal("actual_pay_amount", StringUtil.getBigDecimal(columns[17]));
						record.setDecimal("refund_amount", StringUtil.getBigDecimal(columns[18]));
						record.setDecimal("actual_refund_amount", StringUtil.getBigDecimal(columns[19]));
						record.setDecimal("marketing_amount", StringUtil.getBigDecimal(columns[20]));
						record.setString("cathay_account_no", StringUtils.trimToNull(columns[21])); //国泰支付账户
						//投保、续期、续保 把保单号赋值给外部保单号
						if(Constant.POLICY_BILL.equals(bizType) || Constant.CONTINUOUS_POLICY_BILL.equals(bizType) || Constant.CONTINUOUS_BILL.equals(bizType)){
							record.setString("external_biz_no", policyNo);
						}else{
							record.setString("external_biz_no", bizVouhourNo);
						}

						recordWriter.write(record);
						numOfTunnel++;

					}
					text = null;
				}
				log.info("FileHandleTaskNo:{}  fileName: {}, count:{} ", fileHandleTaskNo, ze.getName(), count.get());
			}
			if(recordWriter != null) {
				recordWriter.close();
			}

			uploadSession.commit();

		}catch(OdpsException odpsException) {
			log.error("FileHandleTaskNo:{}, ODPSException occur:{}", fileHandleTaskNo, odpsException);
			throw new BusinessException("ODPS Exception:{}", odpsException);
		} catch(IOException ioException) {
			log.error("FileHandleTaskNo:{}, IOException occur:{}", fileHandleTaskNo, ioException);
			throw new BusinessException("IO Exception:{}", ioException);
		} catch(JSONException jsonException) {
			log.error("FileHandleTaskNo:{}, text:{}, json com.cathay.recon.core.component.parser exception:{}",fileHandleTaskNo, text, jsonException.getMessage() );
			throw new BusinessException("JSON Exception:{}", jsonException);
		}

		if(watch != null) {
			Long timeCostInSeconds = watch.elapsed(TimeUnit.SECONDS);
			watch.stop();
			log.info("total:" + numOfTunnel + ", time cost:" + timeCostInSeconds +"(s)");
		}

		return FileTunnelDTO.createSuccessTunnelResult(numOfTunnel, fileHandleTaskNo);
	}

